import { IsLatitude, IsLongitude, IsUUID } from 'class-validator';

export class CreateTripDto {
  // Generated by the mobile app. Validated as a UUID so the history
  // lookup (GET /trips?riderId=) can't be fed arbitrary strings.
  @IsUUID()
  riderId: string;

  @IsLatitude()
  originLat: number;

  @IsLongitude()
  originLng: number;

  @IsLatitude()
  destinationLat: number;

  @IsLongitude()
  destinationLng: number;
}
